"use client";
import { useState } from "react";
import handlesubmit from "@/app/actions/server";
import { Getuser } from "@/app/actions/server";
import { Crpost } from "../actions/post";
import Getpost from "../actions/post";
interface Iuser {
  _id?: string;
  name: string;
  userId: string;
}
interface Postblock {
  _id?: string;
  title: string;
  content: string;
}
export default function Adduserpage() {
  const [name, setName] = useState("");
  const [userId, setuserId] = useState("");
  const [userlist, setUserlist] = useState<Iuser[]>([]);
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [postlist, setPostlist] = useState<Postblock[]>([]);
  const [postusername, setPostusername] = useState("");
  const sub = async (e: React.FormEvent) => {
    e.preventDefault();
    const res = await handlesubmit({ name, userId });
    if (res.success) {
      alert("user created!");
    } else {
      alert(res.error);
    }
  };

  const gt = async () => {
    const ft = await Getuser();
    if (ft.success) {
      setUserlist(ft.data);
    } else {
      alert("error occoured failed to get");
    }
  };

  const crtspost = async (e: React.FormEvent) => {
    e.preventDefault();
    const res = await Crpost({
      title,
      content,
      name,
    });

    if (res.success) {
      alert(" post created");
    } else {
      alert(res.error);
    }
  };

  const getpost = async () => {
    const gtpost = await Getpost(postusername);
    if (gtpost) {
      setPostlist(gtpost.data);
    } else {
      alert("failed get the post ");
    }
  };
  return (
    <div className="flex flex-col gap-4 min-h-screen w-full">
      <form
        className="flex flex-col justify-center items-center gap-5  border border-amber-800"
        onSubmit={sub}
      >
        <input
          type="text"
          placeholder="Enter your name"
          value={name}
          onChange={(e) => setName(e.target.value)}
        />

        <input
          type="text"
          value={userId}
          placeholder=" enter your user name"
          onChange={(e) => setuserId(e.target.value)}
        />

        <button className="btn btn-secondary" type="submit">
          Submit
        </button>
      </form>

      <button
        type="button"
        className=" btn btn-secondary w-1/2 mr-[50%]" 
        onClick={gt}
      >
        Get user List
      </button>

      <div className="flex flex-col">
        {userlist.map((ele) => (
          <div key={ele._id} className="flex">
            {ele.name}
          </div>
        ))}
      </div>

      <div className="flex flex-col">
        <input
          type="text"
          placeholder="Enter your name"
          value={postusername}
          onChange={(e) => setPostusername(e.target.value)}
        />

        <button className="btn btn-accent" onClick={getpost}>
          Get all Post
        </button>

        <div className="flex flx-col gap-4 justify-center items-center">
          {postlist.map((ele) => (
            <div key={ele._id} className="nothing">
              <h1> {ele.title} </h1>
              <p> {ele.content} </p>
            </div>
          ))}
        </div>

        <form
          className="flex flex-col justify-center items-center gap-5  border border-amber-800"
          onSubmit={crtspost}
        >
          <input
            type="text"
            placeholder="Enter  content"
            value={content}
            onChange={(e) => setContent(e.target.value)}
          />

          <input
            type="text"
            value={title}
            placeholder=" enter your user name"
            onChange={(e) => setTitle(e.target.value)}
          />

          <button className="btn btn-secondary" type="submit">
            Post
          </button>
        </form>
      </div>
    </div>
  );
}
