"use server";

import { connectdb } from "../lib/db";
import {User} from "@/app/lib/models";
export default async function handlesubmit(data: {
  name: string;
  userId: string;
}) {
  try {
    await connectdb();

    const newuser = await User.create({
      name: data.name,
      userId: data.userId,
    });
    return { successs: true, user: JSON.parse(JSON.stringify({ newuser })) };
  } catch (error) {
    console.error(error);
  }
  return { success: false, error: "Database connection or validation failed" };
}

export async function Getuser() {
  try {
    await connectdb();
    const find = await User.find();
    return {
      success: true,
      data: JSON.parse(JSON.stringify(find)),
    };
  } catch (error) {
    console.error(error);
  }
  return { successs: false, error: "error occoured" };
}
